#!/usr/bin/env python3
"""Atomic execution-model profile switch for Codex LOOP.

Only the ordinary execution family changes. Sol and K3 review roles are
validated but never rewritten. API credentials remain owned by OpenCodex.
"""
from __future__ import annotations

import argparse
import json
import os
import re
import sys
import time
import tomllib
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parents[1]
DEFAULT_CODEX_HOME = Path.home() / ".codex"
DEFAULT_WSL_ROOT = Path(r"\\wsl.localhost\Ubuntu\home\codexloop\codex-loop-s-f2")


class ProfileError(RuntimeError):
    pass


def q(value: str) -> str:
    return json.dumps(value, ensure_ascii=False)


def section_span(text: str, section: str | None) -> tuple[int, int]:
    headers = list(re.finditer(r"(?m)^\s*\[([^]\r\n]+)]\s*(?:#.*)?$", text))
    if section is None:
        return 0, headers[0].start() if headers else len(text)
    for idx, match in enumerate(headers):
        if match.group(1).strip() == section:
            return match.end(), headers[idx + 1].start() if idx + 1 < len(headers) else len(text)
    raise ProfileError(f"missing TOML section [{section}]")


def set_toml_key(text: str, section: str | None, key: str, value: str) -> str:
    start, end = section_span(text, section)
    body = text[start:end]
    rx = re.compile(rf'(?m)^(\s*{re.escape(key)}\s*=\s*)[^\r\n]*(\r?\n|$)')
    replacement = rf"\g<1>{q(value)}\g<2>"
    changed, count = rx.subn(replacement, body, count=1)
    if count != 1:
        where = "top level" if section is None else f"[{section}]"
        raise ProfileError(f"missing or duplicate {where}.{key}")
    return text[:start] + changed + text[end:]


def set_inline_reasoning(text: str, section: str, key: str, effort: str) -> str:
    start, end = section_span(text, section)
    body = text[start:end]
    rx = re.compile(rf'(?m)^(\s*{re.escape(key)}\s*=\s*\{{[^\r\n]*?reasoning\s*=\s*")[^"]+("[^\r\n]*\}}\s*(?:#.*)?)(\r?\n|$)')
    changed, count = rx.subn(rf"\g<1>{effort}\g<2>\g<3>", body, count=1)
    if count != 1:
        raise ProfileError(f"missing inline reasoning for [{section}].{key}")
    return text[:start] + changed + text[end:]


def set_yaml_role(text: str, role: str, model: str, effort: str) -> str:
    rx = re.compile(rf"(?ms)^(  {re.escape(role)}:\s*.*?)(?=^  [A-Za-z_][\w-]*:\s*|\Z)")
    match = rx.search(text)
    if not match:
        raise ProfileError(f"missing YAML role {role}")
    block = match.group(1)
    block, mc = re.subn(r'(?m)^(\s+model:\s*)[^#\r\n]*(\s*(?:#.*)?$)',
                        rf"\g<1>{model}\g<2>", block, count=1)
    block, ec = re.subn(r'(?m)^(\s+reasoning_effort:\s*)\S+(\s*(?:#.*)?$)',
                        rf"\g<1>{effort}\g<2>", block, count=1)
    if mc != 1 or ec != 1:
        raise ProfileError(f"incomplete YAML role {role}")
    return text[:match.start(1)] + block + text[match.end(1):]


def load_profiles(root: Path) -> tuple[dict[str, Any], Path]:
    path = root / "config" / "model_profiles.toml"
    try:
        doc = tomllib.loads(path.read_text(encoding="utf-8"))
    except (OSError, tomllib.TOMLDecodeError) as exc:
        raise ProfileError(f"profile config unreadable: {path}: {exc}") from exc
    profiles = doc.get("profiles")
    if not isinstance(profiles, dict) or not profiles:
        raise ProfileError("no model profiles configured")
    return doc, path


def profile_values(doc: dict[str, Any], name: str) -> tuple[str, str]:
    item = (doc.get("profiles") or {}).get(name)
    if not isinstance(item, dict):
        raise ProfileError(f"unknown profile: {name}")
    model, effort = item.get("execution_model"), item.get("execution_reasoning")
    if not isinstance(model, str) or "/" not in model or not isinstance(effort, str):
        raise ProfileError(f"invalid profile: {name}")
    return model, effort


def project_updates(root: Path, profile_path: Path, name: str,
                    model: str, effort: str) -> dict[Path, str]:
    updates: dict[Path, str] = {}

    def edit(rel: str, fn) -> None:
        path = root / rel
        text = path.read_text(encoding="utf-8")
        updates[path] = fn(text)

    profile_text = profile_path.read_text(encoding="utf-8")
    updates[profile_path] = set_toml_key(profile_text, None, "active_profile", name)

    def v2(text: str) -> str:
        text = set_toml_key(text, "models", "v4_model", model)
        return set_toml_key(text, "models", "v4_reasoning", effort)
    edit("config/orchestration_policy_v2.toml", v2)

    def agent(text: str) -> str:
        text = set_toml_key(text, None, "model", model)
        return set_toml_key(text, None, "model_reasoning_effort", effort)
    for rel in ("agents/worker.toml", "agents/duty_officer.toml"):
        edit(rel, agent)

    def defaults(text: str) -> str:
        text = set_toml_key(text, "agents", "default_subagent_model", model)
        return set_toml_key(text, "agents", "default_subagent_reasoning_effort", effort)
    for rel in (".codex/config.toml", "config/config.toml.example"):
        edit(rel, defaults)

    def roles(text: str) -> str:
        for role in ("executor", "scout", "duty_officer"):
            text = set_yaml_role(text, role, model, effort)
        return text
    edit("config/roles.yaml", roles)
    return updates


def global_updates(codex_home: Path, model: str, effort: str) -> dict[Path, str]:
    updates: dict[Path, str] = {}
    config = codex_home / "config.toml"
    if config.is_file():
        text = set_toml_key(config.read_text(encoding="utf-8"), "agents",
                            "default_subagent_model", model)
        updates[config] = set_toml_key(text, "agents",
                                      "default_subagent_reasoning_effort", effort)
    for name in ("worker", "duty_officer"):
        path = codex_home / "agents" / f"{name}.toml"
        if path.is_file():
            text = set_toml_key(path.read_text(encoding="utf-8"), None, "model", model)
            updates[path] = set_toml_key(text, None, "model_reasoning_effort", effort)
    return updates


def validate_updates(updates: dict[Path, str], model: str, effort: str,
                     root: Path | None = None) -> None:
    for path, text in updates.items():
        if path.suffix == ".toml":
            try:
                tomllib.loads(text)
            except tomllib.TOMLDecodeError as exc:
                raise ProfileError(f"generated invalid TOML {path}: {exc}") from exc
    project_agents = [p for p in updates if p.as_posix().endswith(("agents/worker.toml", "agents/duty_officer.toml"))]
    for path in project_agents:
        doc = tomllib.loads(updates[path])
        if doc.get("model") != model or doc.get("model_reasoning_effort") != effort:
            raise ProfileError(f"execution pin mismatch after generation: {path}")
    if root is not None:
        for name in ("reviewer", "verifier", "plan_expander"):
            path = root / "agents" / f"{name}.toml"
            doc = tomllib.loads(path.read_text(encoding="utf-8"))
            if doc.get("model") != "weiwu-k3/kimi-k3" or doc.get("model_reasoning_effort") != "max":
                raise ProfileError(f"K3 review pin changed unexpectedly: {path}")


def atomic_write(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(f"{path.name}.tmp.{os.getpid()}")
    with tmp.open("w", encoding="utf-8", newline="\n") as handle:
        handle.write(text)
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(tmp, path)


def apply_transaction(updates: dict[Path, str]) -> None:
    originals = {path: (path.read_text(encoding="utf-8") if path.is_file() else None)
                 for path in updates}
    written: list[Path] = []
    try:
        for path, text in updates.items():
            atomic_write(path, text)
            written.append(path)
    except Exception:
        errors = []
        for path in reversed(written):
            try:
                original = originals[path]
                if original is None:
                    path.unlink(missing_ok=True)
                else:
                    atomic_write(path, original)
            except Exception as exc:  # best effort; surface every failed restore
                errors.append(f"{path}: {exc}")
        if errors:
            raise ProfileError("switch failed and rollback was incomplete: " + "; ".join(errors))
        raise


def wsl_updates(wsl_root: Path, local_updates: dict[Path, str], root: Path) -> dict[Path, str]:
    if not wsl_root.is_dir():
        return {}
    result: dict[Path, str] = {}
    for source, text in local_updates.items():
        try:
            rel = source.relative_to(root)
        except ValueError:
            continue
        target = wsl_root / rel
        result[target] = text
    return result


def state(root: Path, doc: dict[str, Any]) -> dict[str, Any]:
    active = str(doc.get("active_profile") or "")
    model, effort = profile_values(doc, active)
    return {"profile": active, "execution_model": model,
            "execution_reasoning": effort}


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description="atomic LOOP execution-model profile switch")
    ap.add_argument("command", choices=["list", "status", "set"])
    ap.add_argument("profile", nargs="?")
    ap.add_argument("--root", type=Path, default=ROOT)
    ap.add_argument("--codex-home", type=Path, default=DEFAULT_CODEX_HOME)
    ap.add_argument("--wsl-root", type=Path, default=DEFAULT_WSL_ROOT)
    ap.add_argument("--no-global", action="store_true")
    ap.add_argument("--no-wsl", action="store_true")
    ap.add_argument("--json", action="store_true")
    args = ap.parse_args(argv)
    root = args.root.resolve()
    doc, profile_path = load_profiles(root)
    if args.command == "list":
        rows = [{"name": name, **value} for name, value in doc["profiles"].items()]
        print(json.dumps(rows, ensure_ascii=False, indent=2) if args.json else
              "\n".join(f"{r['name']}: {r['execution_model']} ({r['execution_reasoning']})" for r in rows))
        return 0
    if args.command == "status":
        value = state(root, doc)
        print(json.dumps(value, ensure_ascii=False) if args.json else
              f"{value['profile']}: {value['execution_model']} ({value['execution_reasoning']})")
        return 0
    if not args.profile:
        ap.error("set requires a profile")
    model, effort = profile_values(doc, args.profile)
    updates = project_updates(root, profile_path, args.profile, model, effort)
    if not args.no_global:
        updates.update(global_updates(args.codex_home.resolve(), model, effort))
    if not args.no_wsl:
        updates.update(wsl_updates(args.wsl_root, updates, root))
    validate_updates(updates, model, effort, root)
    apply_transaction(updates)
    marker = {"schema": "codex-loop-model-profile-state/v1", "ts": time.time(),
              "profile": args.profile, "execution_model": model,
              "execution_reasoning": effort, "updated_files": len(updates)}
    atomic_write(root / "data" / "governor" / "model_profile.json",
                 json.dumps(marker, ensure_ascii=False, indent=2) + "\n")
    print(json.dumps(marker, ensure_ascii=False) if args.json else
          f"{args.profile}: {model} ({effort}); updated {len(updates)} files")
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except (OSError, ProfileError) as exc:
        print(f"model profile switch failed: {exc}", file=sys.stderr)
        raise SystemExit(2)

#!/usr/bin/env python3
"""refill_controller_v2.py 鈥?Pool-aware sustained refill (P0-6 fix, 搂2.6).

Fixes the demand side of the K3 starvation:

* **``queue_sync_ledger`` is pool-aware and total.**  The shipped
  ``refill_controller.py:203-208`` counted DISPATCHABLE packets into a single
  ``--pool`` argument defaulting to ``"v4"``, so K3-pool demand was never
  written and the configured K3 reservation was permanently borrowed by V4.
  v2 derives the pool per packet from role/``pool_hint`` metadata
  (verifier/reviewer/plan_expander 鈫?``k3``, else ``v4``) and counts the K3
  work states (``L2_VERIFY``, ``EXPAND_K3``, ``L2_RANK``) as K3 demand.  The
  sync writes BOTH pools in one atomic mutation; the ``--pool`` flag no
  longer applies to sync (it stays for manual ``queue-add``/``remove`` ops).
* **Configured K3 target with actual demand matching:** targets/low-waters come
  fail-closed from ``refill_policy.toml`` (the only concurrency authority;
  policy unreadable => :class:`PolicyError`, never the silent divergent
  16/16-vs-48 defaults of v1).  A pool refills only when it has pending work
  AND its running count is below its low water 鈥?demand-backed, never idle
  filling (anti-pattern canary: zero demand 鈬?zero K3 spawns).
* **Reservations borrowable (true):** when only one pool has pending work it
  may borrow the other pool's reservation up to ``target_total``; watermark
  logic reclaims borrowed slots naturally once K3 demand exists.
* **Policy-version stamping:** ``refill_state.json`` records the policy
  version + mtime it was computed from; a mismatch on read forces a
  recompute, so a stale state file can never silently win (P0-8.3).
"""
from __future__ import annotations

import argparse
import ctypes
import json
import os
import sys
import time
from ctypes import wintypes
from pathlib import Path
from typing import Any, Callable, Final, Mapping

try:
    from orchestration_common import (LoopPaths, PolicyError, RefillPolicy,
                                      append_ndjson, atomic_write_json, file_lock,
                                      get_logger, read_json, utc_now)
except ImportError:  # pragma: no cover - direct CLI execution
    sys.path.insert(0, str(Path(__file__).resolve().parent))
    from orchestration_common import (LoopPaths, PolicyError, RefillPolicy,
                                      append_ndjson, atomic_write_json, file_lock,
                                      get_logger, read_json, utc_now)

__all__ = [
    "POOLS",
    "K3_ROLES",
    "K3_WORK_STATES",
    "pool_for_packet",
    "RefillControllerV2",
    "main",
]

log = get_logger("loop.refill_controller_v2")

POOLS: Final[tuple[str, str]] = ("v4", "k3")
STATE_SCHEMA: Final[str] = "codex-loop-refill/v3"
QUEUE_SCHEMA: Final[str] = "codex-loop-refill-queue/v2"

#: Roles whose packets are K3 demand.
K3_ROLES: Final[frozenset[str]] = frozenset({"verifier", "reviewer", "plan_expander"})
#: v2 state-machine states that ARE K3 work (count as K3 demand while active).
K3_WORK_STATES: Final[frozenset[str]] = frozenset(
    {"L2_VERIFY", "L2_RANK", "EXPAND_K3", "L2_VERIFY_PENDING"})
NATIVE_RUNNING_TTL_SECONDS: Final[float] = 1800.0


def _process_start_token(pid: Any) -> int | None:
    try:
        pid = int(pid)
    except (TypeError, ValueError):
        return None
    if os.name == "nt":
        handle = ctypes.windll.kernel32.OpenProcess(0x1000, False, pid)
        if not handle:
            return None
        try:
            code = wintypes.DWORD()
            if (not ctypes.windll.kernel32.GetExitCodeProcess(
                    handle, ctypes.byref(code)) or code.value != 259):
                return None
            creation = wintypes.FILETIME(); exit_time = wintypes.FILETIME()
            kernel = wintypes.FILETIME(); user = wintypes.FILETIME()
            if not ctypes.windll.kernel32.GetProcessTimes(
                    handle, ctypes.byref(creation), ctypes.byref(exit_time),
                    ctypes.byref(kernel), ctypes.byref(user)):
                return None
            return ((int(creation.dwHighDateTime) << 32)
                    | int(creation.dwLowDateTime))
        finally:
            ctypes.windll.kernel32.CloseHandle(handle)
    try:
        return int(Path("/proc/%d/stat" % pid).read_text(
            encoding="ascii").split()[21])
    except (OSError, ValueError, IndexError):
        return None


def _process_generation_alive(pid: Any, expected: Any) -> bool:
    actual = _process_start_token(pid)
    if actual is None:
        return False
    try:
        return expected is not None and actual == int(expected)
    except (TypeError, ValueError):
        return False


def pool_for_packet(item: Mapping[str, Any]) -> str:
    """Mechanically derive the pool for a ledger packet entry.

    Priority: explicit ``pool_hint`` > role (verifier/reviewer/plan_expander
    鈫?k3) > default v4.  Zero-model, deterministic (搂2.6.1)."""
    hint = item.get("pool_hint")
    if isinstance(hint, str) and hint in POOLS:
        return hint
    role = str(item.get("role") or "")
    return "k3" if role in K3_ROLES else "v4"


def classify_pool(model: Any) -> str:
    """Route an *observed* agent model string into v4/k3 (accounting only)."""
    value = str(model or "").lower()
    return "k3" if ("k3" in value or "r1" in value or "reasoner" in value) else "v4"


class RefillControllerV2:
    """Mechanical, pool-aware refill state machine.

    The controller never calls the host spawn API: it publishes
    machine-readable ``refill_required`` records carrying per-pool deficits
    and keeps unfulfilled debt fail-visible (unchanged v1 contract)."""

    def __init__(self, paths: LoopPaths | None = None) -> None:
        self.paths = paths or LoopPaths.resolve()
        self.policy = RefillPolicy.load(self.paths)   # fail-closed (PolicyError)
        self.refill_dir = self.paths.refill_dir
        self.state_path = self.refill_dir / "refill_state.json"
        self.queue_path = self.refill_dir / "work_queue.json"
        self.events_path = self.refill_dir / "events.ndjson"
        self.lock_path = self.refill_dir / ".refill.lock"
        self.roster_path = self.paths.data / "lifecycle" / "native_roster.json"
        self.exec_roster_path = self.paths.data / "lifecycle" / "exec_roster.json"

    # ------------------------------------------------------------------ config
    def targets(self) -> dict[str, int]:
        return {"v4": self.policy.v4_target(), "k3": self.policy.k3_target()}

    def low_waters(self) -> dict[str, int]:
        return {"v4": min(self.policy.v4_target(), self.policy.v4_low_water()),
                "k3": min(self.policy.k3_target(), self.policy.k3_low_water())}

    def target_total(self) -> int:
        return self.policy.target_total()

    # ------------------------------------------------------------------ queue
    def read_queue(self) -> dict[str, int]:
        doc = read_json(self.queue_path, {}) or {}
        pools = doc.get("pools", {}) if isinstance(doc, dict) else {}
        return {p: max(0, int(pools.get(p, 0) or 0)) for p in POOLS}

    def _write_queue_unlocked(self, pools: Mapping[str, int]) -> dict[str, int]:
        clean = {p: max(0, int(pools.get(p, 0) or 0)) for p in POOLS}
        atomic_write_json(self.queue_path,
                          {"schema": QUEUE_SCHEMA, "pools": clean,
                           "updated_at": utc_now()})
        return clean

    def _queue_mutate(self, fn: Callable[[dict[str, int]], None]) -> dict[str, int]:
        with file_lock(self.lock_path):
            pools = self.read_queue()
            fn(pools)
            return self._write_queue_unlocked(pools)

    def queue_set(self, count: int, pool: str) -> dict[str, int]:
        return self._queue_mutate(lambda p: p.__setitem__(pool, int(count)))

    def queue_add(self, count: int, pool: str) -> dict[str, int]:
        return self._queue_mutate(
            lambda p: p.__setitem__(pool, p.get(pool, 0) + int(count)))

    def queue_remove(self, count: int, pool: str) -> dict[str, int]:
        return self._queue_mutate(
            lambda p: p.__setitem__(pool, max(0, p.get(pool, 0) - int(count))))

    def queue_clear(self) -> dict[str, int]:
        with file_lock(self.lock_path):
            return self._write_queue_unlocked({p: 0 for p in POOLS})

    def queue_sync_ledger(self) -> dict[str, int]:
        """THE P0-6 FIX: pool-aware, total ledger sync.

        Counts every DISPATCHABLE packet into its mechanically derived pool
        and every K3 work state as K3 demand, then replaces BOTH pool counts
        atomically.  No ``--pool`` parameter: sync is total by definition.
        """
        led = read_json(self.paths.ledger, {"packets": {}}) or {"packets": {}}
        ready = {p: 0 for p in POOLS}
        for pid, item in led.get("packets", {}).items():
            if not isinstance(item, dict):
                continue
            state = item.get("state")
            if state == "DISPATCHABLE":
                ready[pool_for_packet(item)] += 1
            elif state in K3_WORK_STATES:
                ready["k3"] += 1
        result = self._queue_mutate(lambda pools: pools.update(ready))
        log.info("queue_sync_ledger: %s", result)
        return result

    # ------------------------------------------------------------------ observed state
    def read_roster_counts(self) -> dict[str, dict[str, int]]:
        """Running/initializing per pool from native + exec rosters.
        Only ``running`` counts as effective concurrency (v1 contract)."""
        keys = ("initializing", "running", "idle", "completed", "shutdown_pending")
        counts = {p: {k: 0 for k in keys} for p in POOLS}
        now = time.time()
        roster = read_json(self.roster_path, {"agents": {}}) or {"agents": {}}
        for item in (roster.get("agents") or {}).values():
            if not isinstance(item, dict):
                continue
            role = str(item.get("agent_role") or item.get("role") or "")
            pool = ("k3" if role in K3_ROLES else "v4") if role else classify_pool(item.get("model"))
            status = str(item.get("status") or "")
            if status == "running":
                try:
                    observed_at = float(item.get("updated_at") or
                                        item.get("started_at") or 0)
                except (TypeError, ValueError):
                    observed_at = 0.0
                if observed_at <= 0 or now - observed_at > NATIVE_RUNNING_TTL_SECONDS:
                    continue
            if status in counts[pool]:
                counts[pool][status] += 1
        for item in (roster.get("pending") or []):
            if not isinstance(item, dict) or item.get("status") != "pending_start":
                continue
            role = str(item.get("agent_role") or "")
            pool = ("k3" if role in K3_ROLES else "v4") if role else classify_pool(item.get("model"))
            counts[pool]["initializing"] += 1
        exec_roster = read_json(self.exec_roster_path, {"jobs": {}}) or {"jobs": {}}
        for item in (exec_roster.get("jobs") or {}).values():
            if not isinstance(item, dict):
                continue
            state = str(item.get("state") or "")
            key = ("initializing" if state == "starting"
                   else "running" if state == "running" else None)
            if key is None:
                continue
            supervisor_alive = _process_generation_alive(
                item.get("supervisor_pid"), item.get("supervisor_proc_start_ticks"))
            worker_alive = _process_generation_alive(
                item.get("os_pid"), item.get("worker_proc_start_ticks"))
            if not supervisor_alive or (key == "running" and not worker_alive):
                continue
            role = str(item.get("role") or item.get("agent_role") or "")
            pool = ("k3" if role in K3_ROLES else "v4") if role else classify_pool(item.get("model"))
            counts[pool][key] += 1
        return counts

    # ------------------------------------------------------------------ recompute
    def recompute(self, emit: bool = True) -> dict[str, Any]:
        """Recompute the refill state with borrowable reservations.

        Demand matching: a pool is refill-required only when IT has pending
        work and its own running count is below its own low water.  With
        ``reservations_borrowable=true`` and only one active pool, that pool
        may use the full ``target_total``; as soon as the other pool gains
        pending work its preferred reservation is honoured again (watermark
        reclaim; 搂2.6.3)."""
        preferred_targets = self.targets()
        preferred_low_waters = self.low_waters()
        target_total = self.target_total()
        borrowable = self.policy.reservations_borrowable()
        pending = self.read_queue()
        pending_total = sum(pending.values())
        targets = dict(preferred_targets)
        low_waters = dict(preferred_low_waters)
        active_pools = [p for p in POOLS if pending[p] > 0]
        if borrowable and len(active_pools) == 1:
            only = active_pools[0]
            targets = {p: (target_total if p == only else 0) for p in POOLS}
            shared_low = min(target_total, sum(preferred_low_waters.values()))
            low_waters = {p: (shared_low if p == only else 0) for p in POOLS}

        counts = self.read_roster_counts()
        running = {p: counts[p]["running"] for p in POOLS}
        initializing = {p: counts[p]["initializing"] for p in POOLS}
        running_total = sum(running.values())
        initializing_total = sum(initializing.values())
        prior = read_json(self.state_path, {}) or {}
        finalized = bool(prior.get("finalized"))
        queue_empty = pending_total <= 0

        # Sustained refill means demand-backed slots are restored to target,
        # not left parked at the low-water trigger.  Low water remains an
        # urgency/hysteresis signal exposed in state; the debt target is the
        # declared policy capacity (currently 60/45/15).
        required = {p: bool(not queue_empty and not finalized
                            and pending[p] > 0 and running[p] < targets[p])
                    for p in POOLS}
        required_any = any(required.values())
        # Debt = min(pending, target 鈭?running); initializing births reserve
        # capacity but never clear debt (fail-visible until observed running).
        raw_debt = {p: (min(pending[p], max(0, targets[p] - running[p]))
                        if required[p] else 0) for p in POOLS}
        raw_spawn = {p: max(0, raw_debt[p] - initializing[p]) for p in POOLS}
        capacity = max(0, target_total - running_total - initializing_total)
        deficit_total = min(sum(raw_spawn.values()), capacity) if required_any else 0
        deficit = self._split_deficit(deficit_total, raw_spawn)

        if queue_empty:
            reason = "queue_empty"
        elif finalized:
            reason = "release_finalize"
        elif required_any and deficit_total == 0:
            reason = "at_capacity"
        elif required_any:
            reason = ("below_low_water" if any(
                required[p] and running[p] < low_waters[p] for p in POOLS)
                else "below_target")
        else:
            reason = "at_or_above_low_water"

        state: dict[str, Any] = {
            "schema": STATE_SCHEMA,
            "policy_version": self.policy.policy_version(),
            "policy_mtime": self._policy_mtime(),
            "target": targets,
            "preferred_target": preferred_targets,
            "target_total": target_total,
            "low_water": low_waters,
            "preferred_low_water": preferred_low_waters,
            "reservations_borrowable": borrowable,
            "pending": {"total": pending_total, **pending},
            "active": {"total": running_total, **running},
            "initializing": {"total": initializing_total, **initializing},
            "refill_required": required_any,
            "refill_required_by_pool": required,
            "deficit": {"total": deficit_total, **deficit},
            "unfulfilled_demand": {"total": sum(raw_debt.values()), **raw_debt},
            "model_pool": sorted(p for p in POOLS if raw_debt[p] > 0),
            "queue_empty": queue_empty,
            "finalized": finalized,
            "reason": reason,
            "refilled": False,
            "updated_at": utc_now(),
        }
        if emit:
            with file_lock(self.lock_path):
                atomic_write_json(self.state_path, state)
            if required_any:
                self._append_event("refill_required",
                                   {"deficit": deficit,
                                    "model_pool": state["model_pool"],
                                    "pending": pending, "running": running})
            elif prior.get("refill_required"):
                self._append_event("refill_clear", {"pending": pending})
        return state

    @staticmethod
    def _split_deficit(total: int, pending: Mapping[str, int]) -> dict[str, int]:
        """Hamilton (largest remainder) split across pools (v1 algorithm)."""
        out = {p: 0 for p in POOLS}
        pools = [p for p in POOLS if pending.get(p, 0) > 0]
        if total <= 0 or not pools:
            return out
        grand = sum(pending[p] for p in pools)
        floors = {p: total * pending[p] // grand for p in pools}
        remainders = {p: total * pending[p] % grand for p in pools}
        remaining = total - sum(floors.values())
        for p in sorted(pools, key=lambda q: remainders[q], reverse=True):
            if remaining <= 0:
                break
            if floors[p] < pending[p]:
                floors[p] += 1
                remaining -= 1
        for p in pools:
            out[p] = min(floors[p], pending[p])
        return out

    # ------------------------------------------------------------------ state guards
    def read_state(self) -> dict[str, Any]:
        """Read the persisted state; a policy version/mtime mismatch forces a
        recompute so stale numbers can never silently win (P0-8.3)."""
        state = read_json(self.state_path, None)
        if not isinstance(state, dict):
            return self.recompute(emit=True)
        if (state.get("policy_version") != self.policy.policy_version()
                or state.get("policy_mtime") != self._policy_mtime()):
            log.warning("refill state computed from stale policy "
                        "(version %r vs %r) 鈥?recomputing",
                        state.get("policy_version"),
                        self.policy.policy_version())
            return self.recompute(emit=True)
        return state

    def _policy_mtime(self) -> float | None:
        try:
            return self.policy.path.stat().st_mtime if self.policy.path else None
        except OSError:
            return None

    # ------------------------------------------------------------------ lifecycle
    def release_finalize(self) -> dict[str, Any]:
        state = read_json(self.state_path, {}) or {}
        state["finalized"] = True
        atomic_write_json(self.state_path, state)
        return self.recompute(emit=True)

    def resume(self) -> dict[str, Any]:
        state = read_json(self.state_path, {}) or {}
        state["finalized"] = False
        atomic_write_json(self.state_path, state)
        return self.recompute(emit=True)

    def _append_event(self, event: str, detail: Mapping[str, Any]) -> None:
        append_ndjson(self.events_path,
                      {"ts": utc_now(), "event": event, **detail})


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------
def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(
        description="Pool-aware sustained-refill controller v2. "
                    "Prints refill_state.json after the requested action.")
    ap.add_argument("--root", type=Path, default=None)
    ap.add_argument("--status", action="store_true")
    ap.add_argument("--recompute", action="store_true")
    ap.add_argument("--queue-set", type=int, metavar="N")
    ap.add_argument("--queue-add", type=int, metavar="N")
    ap.add_argument("--queue-remove", type=int, metavar="N")
    ap.add_argument("--queue-clear", action="store_true")
    ap.add_argument("--queue-sync-ledger", action="store_true",
                    help="pool-aware TOTAL sync from the progress ledger "
                         "(--pool does not apply; sync writes both pools)")
    ap.add_argument("--pool", choices=list(POOLS), default="v4",
                    help="pool for manual queue-set/add/remove ops only")
    ap.add_argument("--release-finalize", action="store_true")
    ap.add_argument("--resume", action="store_true")
    args = ap.parse_args(argv)
    try:
        ctl = RefillControllerV2(LoopPaths.resolve(args.root))
    except PolicyError as exc:
        # Fail closed AND visible: emit the error event, exit non-zero.
        print(json.dumps({"error": str(exc), "fail_closed": True}),
              file=sys.stderr)
        return 1
    mutated = False
    if args.queue_set is not None:
        ctl.queue_set(args.queue_set, args.pool); mutated = True
    if args.queue_add is not None:
        ctl.queue_add(args.queue_add, args.pool); mutated = True
    if args.queue_remove is not None:
        ctl.queue_remove(args.queue_remove, args.pool); mutated = True
    if args.queue_clear:
        ctl.queue_clear(); mutated = True
    if args.queue_sync_ledger:
        ctl.queue_sync_ledger(); mutated = True
    if args.release_finalize:
        ctl.release_finalize(); mutated = True
    if args.resume:
        ctl.resume(); mutated = True
    out = ctl.read_state() if (args.status and not mutated) \
        else ctl.recompute(emit=True)
    print(json.dumps(out, ensure_ascii=False, sort_keys=True))
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Mechanical actuator for the canonical v2 refill controller.

This module is deliberately not another controller.  It synchronizes demand
from the packet ledger, asks :class:`RefillControllerV2` for the bounded
deficit, emits a packet-only manifest, and hands that manifest to the existing
``headless_wave`` transport.  It never invents work or embeds a free-form
prompt: every task must resolve to a validated ``data/packets/<id>.json`` and
is physically dispatched by ``DispatcherV2``.
"""
from __future__ import annotations

import argparse
import json
import os
import subprocess
import sys
import time
from pathlib import Path
from typing import Any, Mapping

try:
    import headless_wave
    from dispatch_v2 import validate_packet_id
    from orchestration_common import (LoopPaths, atomic_write_json, file_lock,
                                      read_json)
    from refill_controller_v2 import (K3_ROLES, K3_WORK_STATES,
                                      RefillControllerV2, pool_for_packet)
except ImportError:  # pragma: no cover - direct execution
    sys.path.insert(0, str(Path(__file__).resolve().parent))
    import headless_wave
    from dispatch_v2 import validate_packet_id
    from orchestration_common import (LoopPaths, atomic_write_json, file_lock,
                                      read_json)
    from refill_controller_v2 import (K3_ROLES, K3_WORK_STATES,
                                      RefillControllerV2, pool_for_packet)


K3_ROLE_BY_STATE = {
    "EXPAND_K3": "plan_expander",
    "L2_VERIFY": "verifier",
    "L2_VERIFY_PENDING": "verifier",
    "L2_RANK": "verifier",
}


class RefillConsumerError(RuntimeError):
    pass


def _process_alive(pid: int) -> bool:
    try:
        if os.name == "nt":
            import ctypes
            from ctypes import wintypes
            handle = ctypes.windll.kernel32.OpenProcess(0x1000, False, int(pid))
            if not handle:
                return False
            try:
                code = wintypes.DWORD()
                return bool(ctypes.windll.kernel32.GetExitCodeProcess(
                    handle, ctypes.byref(code))) and code.value == 259
            finally:
                ctypes.windll.kernel32.CloseHandle(handle)
        os.kill(int(pid), 0)
        return True
    except (OSError, TypeError, ValueError):
        return False


def _proc_start_ticks(pid: int) -> int | None:
    if os.name == "nt":
        try:
            import ctypes
            from ctypes import wintypes
            handle = ctypes.windll.kernel32.OpenProcess(0x1000, False, int(pid))
            if not handle:
                return None
            try:
                creation = wintypes.FILETIME()
                exit_time = wintypes.FILETIME()
                kernel = wintypes.FILETIME()
                user = wintypes.FILETIME()
                if not ctypes.windll.kernel32.GetProcessTimes(
                        handle, ctypes.byref(creation), ctypes.byref(exit_time),
                        ctypes.byref(kernel), ctypes.byref(user)):
                    return None
                return ((int(creation.dwHighDateTime) << 32)
                        | int(creation.dwLowDateTime))
            finally:
                ctypes.windll.kernel32.CloseHandle(handle)
        except (OSError, TypeError, ValueError):
            return None
    try:
        return int(Path("/proc/%d/stat" % int(pid)).read_text(
            encoding="ascii").split()[21])
    except (OSError, TypeError, ValueError, IndexError):
        return None


def _process_generation_alive(pid: int, ticks: int | None) -> bool:
    return ticks is not None and _process_alive(pid) \
        and _proc_start_ticks(pid) == int(ticks)


def schedule_run(root: Path, *, source: str) -> dict[str, Any]:
    """Coalesce and detach the packet-only refill actuator.

    Desktop lifecycle events must not invoke the full orchestration epilogue:
    that would also drain the shared audit event stream.  This runner performs
    only the existing packet-ledger refill transaction and therefore cannot
    invent work or mutate the state machine from transport-only events.
    """
    root = Path(root).resolve()
    orchestration = root / "data" / "orchestration"
    orchestration.mkdir(parents=True, exist_ok=True)
    marker = orchestration / "refill_actuator.pid"
    requests = orchestration / "refill_requests.json"
    log_path = orchestration / "refill_actuator.log"
    claim = orchestration / ".refill_actuator_schedule.lock"
    with file_lock(claim):
        request_state = read_json(requests, {"requested_seq": 0,
                                             "consumed_seq": 0}) or {}
        request_state["requested_seq"] = int(
            request_state.get("requested_seq", 0) or 0) + 1
        request_state.update(source=source, updated_at=time.time())
        atomic_write_json(requests, request_state)
        try:
            marker_value = read_json(marker, {}) or {}
            prior_pid = int(marker_value["pid"])
            prior_ticks = int(marker_value["proc_start_ticks"])
        except (KeyError, TypeError, ValueError):
            prior_pid, prior_ticks = 0, None
        if prior_pid and _process_generation_alive(prior_pid, prior_ticks):
            return {"status": "coalesced", "pid": prior_pid, "source": source}
        log = log_path.open("ab")
        kwargs: dict[str, Any] = {
            "cwd": str(root), "env": {**os.environ, "LOOP_ROOT": str(root)},
            "stdin": subprocess.DEVNULL, "stdout": log, "stderr": subprocess.STDOUT,
            "close_fds": True,
        }
        if os.name == "nt":
            kwargs["creationflags"] = (getattr(subprocess, "CREATE_NO_WINDOW", 0)
                                       | getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0))
        else:
            kwargs["start_new_session"] = True
        try:
            proc = subprocess.Popen(
                [sys.executable, str(root / "harness" / "refill_consumer_v2.py"),
                 "--root", str(root), "--source", source], **kwargs)
            atomic_write_json(marker, {"pid": proc.pid,
                                       "proc_start_ticks": _proc_start_ticks(proc.pid)})
            return {"status": "scheduled", "pid": proc.pid, "source": source,
                    "log": str(log_path)}
        finally:
            log.close()


def schedule_delayed_run(root: Path, *, wake_at: float,
                         source: str) -> dict[str, Any]:
    """Schedule one detached wake after provider/transport backoff expires."""
    root = Path(root).resolve()
    orchestration = root / "data" / "orchestration"
    orchestration.mkdir(parents=True, exist_ok=True)
    marker = orchestration / "refill_backoff_wake.json"
    with file_lock(orchestration / ".refill_backoff_wake.lock"):
        old = read_json(marker, {}) or {}
        try:
            old_pid = int(old.get("pid", 0) or 0)
            old_ticks = int(old.get("proc_start_ticks"))
            old_wake = float(old.get("wake_at", 0) or 0)
        except (TypeError, ValueError):
            old_pid, old_ticks, old_wake = 0, None, 0.0
        if (old_pid and _process_generation_alive(old_pid, old_ticks)
                and old_wake <= wake_at):
            return {"status": "coalesced", "pid": old_pid,
                    "wake_at": old_wake, "source": source}
        delay = max(0.0, wake_at - time.time())
        log = (orchestration / "refill_actuator.log").open("ab")
        kwargs: dict[str, Any] = {
            "cwd": str(root), "env": {**os.environ, "LOOP_ROOT": str(root)},
            "stdin": subprocess.DEVNULL, "stdout": log,
            "stderr": subprocess.STDOUT, "close_fds": True,
        }
        if os.name == "nt":
            kwargs["creationflags"] = (getattr(subprocess, "CREATE_NO_WINDOW", 0)
                                       | getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0))
        else:
            kwargs["start_new_session"] = True
        try:
            proc = subprocess.Popen(
                [sys.executable, str(root / "harness" / "refill_consumer_v2.py"),
                 "--root", str(root), "--source", source,
                 "--delay", "%.3f" % delay], **kwargs)
            atomic_write_json(marker, {"pid": proc.pid,
                                       "proc_start_ticks": _proc_start_ticks(proc.pid),
                                       "wake_at": wake_at, "source": source})
            return {"status": "scheduled", "pid": proc.pid,
                    "wake_at": wake_at, "source": source}
        finally:
            log.close()


def schedule_retry_if_debt(root: Path, state: Mapping[str, Any],
                           *, source: str) -> dict[str, Any] | None:
    if int((state.get("deficit") or {}).get("total", 0) or 0) <= 0:
        return None
    now = time.time()
    wake_at = now + 30.0
    health_dir = Path(root) / "data" / "provider_health"
    for path in health_dir.glob("*.json") if health_dir.exists() else ():
        doc = read_json(path, {}) or {}
        try:
            until = float(doc.get("backoff_until", 0) or 0)
        except (TypeError, ValueError):
            continue
        if until > now:
            wake_at = max(wake_at, until + 1.0)
    return schedule_delayed_run(Path(root), wake_at=wake_at, source=source)


def role_for_entry(entry: Mapping[str, Any]) -> str:
    state = str(entry.get("state") or "")
    if state in K3_ROLE_BY_STATE:
        return K3_ROLE_BY_STATE[state]
    role = str(entry.get("role") or "")
    if role in {"worker", "verifier", "reviewer", "plan_expander"}:
        return role
    raise RefillConsumerError(
        "DISPATCHABLE packet lacks an explicit LOOP role; refusing inherited/default model")


def validate_packet(paths: LoopPaths, packet_id: str) -> dict[str, Any]:
    validate_packet_id(packet_id)
    packet = read_json(paths.data / "packets" / (packet_id + ".json"), None)
    if not isinstance(packet, dict) or packet.get("packet_id") != packet_id:
        raise RefillConsumerError("packet file missing or id mismatch: %s" % packet_id)
    for key in ("goal", "authorized_paths", "acceptance"):
        if key not in packet:
            raise RefillConsumerError("packet %s missing %s" % (packet_id, key))
    return packet


def select_tasks(paths: LoopPaths, state: Mapping[str, Any]) -> list[dict[str, Any]]:
    """Select real packets up to the controller's per-pool deficit."""
    ledger = read_json(paths.ledger, {"packets": {}}) or {"packets": {}}
    deficits = state.get("deficit") if isinstance(state, Mapping) else {}
    remaining = {pool: max(0, int((deficits or {}).get(pool, 0) or 0))
                 for pool in ("v4", "k3")}
    tasks: list[dict[str, Any]] = []
    parent_states = read_json(paths.refill_dir / "parent_sessions.json",
                              {"parents": {}}) or {"parents": {}}
    for packet_id in sorted((ledger.get("packets") or {}).keys()):
        entry = ledger["packets"].get(packet_id)
        if not isinstance(entry, dict):
            continue
        state_name = str(entry.get("state") or "")
        # Dedicated K3 states are demand signals consumed by L2Consumer or
        # the plan pipeline; dispatching their source packet here would create
        # a duplicate verifier/expander.  This generic actuator owns only the
        # mechanically DISPATCHABLE packet lane.
        if state_name != "DISPATCHABLE":
            continue
        if entry.get("release_review"):
            # Release reviews have a dedicated once-per-wave hard-pinned
            # dispatcher and must never be consumed as ordinary refill work.
            continue
        parent_id = entry.get("parent_session_id")
        if entry.get("parent_enabled"):
            parent = (parent_states.get("parents") or {}).get(str(parent_id))
            if not isinstance(parent, dict) or parent.get("active") is not True:
                # Imported work cannot outlive its explicitly registered
                # parent.  The deficit remains visible, but no new birth is
                # admitted after Stop/inactivation.
                continue
        pool = pool_for_packet(entry)
        if remaining[pool] <= 0:
            continue
        packet = validate_packet(paths, str(packet_id))
        role = role_for_entry(entry)
        role_pool = "k3" if role in K3_ROLES else "v4"
        if role_pool != pool:
            raise RefillConsumerError(
                "packet %s pool/role conflict: %s vs %s" %
                (packet_id, pool, role))
        tasks.append({
            "task_id": str(packet_id),
            "task_name": str(entry.get("task_name") or packet.get("goal")
                             or packet_id)[:160],
            "packet_id": str(packet_id),
            "role": role,
            # Parent provenance is control metadata, not an execution
            # override.  It is deliberately propagated so lifecycle and the
            # dashboard can attribute a birth to the owning parent session.
            **({"parent_session_id": str(entry["parent_session_id"])}
               if entry.get("parent_session_id") else {}),
            **({"manifest_id": str(entry["manifest_id"])}
               if entry.get("manifest_id") else {}),
        })
        remaining[pool] -= 1
    return tasks


def build_manifest(paths: LoopPaths, state: Mapping[str, Any]) -> Path | None:
    tasks = select_tasks(paths, state)
    if not tasks:
        return None
    path = paths.refill_dir / "packet_wave.json"
    atomic_write_json(path, {
        "schema": "codex-loop-packet-wave/v1",
        "policy_version": state.get("policy_version"),
        "deficit_snapshot": state.get("deficit"),
        "tasks": tasks,
    })
    return path


def run_once(root: Path, *, dry_run: bool = False,
             observe_timeout: float = 5.0) -> tuple[int, dict[str, Any]]:
    paths = LoopPaths.resolve(root)
    # One actuator transaction per LOOP root.  The controller has its own
    # short state lock; this separate lock spans selection through stable
    # roster observation and closes the pre-roster double-birth race.
    with file_lock(paths.refill_dir / ".consumer.lock"):
        controller = RefillControllerV2(paths)
        controller.queue_sync_ledger()
        before = controller.recompute()
        manifest = build_manifest(paths, before)
        if manifest is None:
            return 0, {"status": "idle", "state": before, "manifest": None}
        args = argparse.Namespace(
            manifest=manifest, root=paths.root, timeout=1800.0,
            observe_timeout=observe_timeout,
            spawn_interval_ms=controller.policy.spawn_interval_ms(),
            health_every=8, dry_run=dry_run,
        )
        rc = headless_wave.run(args)
        # Dispatch appends canonical ``dispatched`` events.  Consume them in
        # the same actuator transaction so a stably born packet immediately
        # leaves DISPATCHABLE; otherwise the debt remains selectable until an
        # unrelated terminal edge and the same packet can be offered again.
        try:
            from statemachine_v2 import StateMachine
            state_machine = StateMachine(paths).step()
        except Exception as exc:
            state_machine = {"status": "failed",
                             "error": "%s: %s" % (type(exc).__name__, exc)}
            rc = rc or 3
        controller.queue_sync_ledger()
        after = controller.recompute()
        retry_wake = (schedule_retry_if_debt(
            root, after, source="refill_debt_backoff") if rc and not dry_run else None)
        return rc, {"status": "dry_run" if dry_run else "dispatched",
                    "manifest": str(manifest), "before": before,
                    "state_machine": state_machine, "after": after,
                    "retry_wake": retry_wake}


def drain_requested(root: Path, *, source: str, dry_run: bool = False,
                    observe_timeout: float = 5.0) -> tuple[int, dict[str, Any]]:
    """Drain every durable refill edge, including edges coalesced mid-run."""
    root = Path(root).resolve()
    orchestration = root / "data" / "orchestration"
    orchestration.mkdir(parents=True, exist_ok=True)
    requests = orchestration / "refill_requests.json"
    marker = orchestration / "refill_actuator.pid"
    claim = orchestration / ".refill_actuator_schedule.lock"
    overall_rc = 0
    passes: list[dict[str, Any]] = []
    while True:
        request_state = read_json(requests, {"requested_seq": 1,
                                             "consumed_seq": 0}) or {}
        requested = int(request_state.get("requested_seq", 1) or 1)
        rc, result = run_once(root, dry_run=dry_run,
                              observe_timeout=observe_timeout)
        overall_rc = overall_rc or rc
        passes.append(result)
        with file_lock(claim):
            latest = read_json(requests, request_state) or request_state
            latest["consumed_seq"] = max(
                int(latest.get("consumed_seq", 0) or 0), requested)
            latest["consumed_at"] = time.time()
            atomic_write_json(requests, latest)
            if int(latest.get("requested_seq", 0) or 0) <= requested:
                marker_value = read_json(marker, {}) or {}
                if (isinstance(marker_value, dict)
                        and int(marker_value.get("pid", -1) or -1) == os.getpid()):
                    try:
                        marker.unlink()
                    except FileNotFoundError:
                        pass
                return overall_rc, {"status": passes[-1].get("status", "idle"),
                                    "source": source, "passes": passes,
                                    "requested_seq": requested,
                                    "consumed_seq": latest["consumed_seq"]}


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description="Actuate real v2 refill packets once")
    ap.add_argument("--root", type=Path, default=Path(__file__).resolve().parents[1])
    ap.add_argument("--observe-timeout", type=float, default=5.0)
    ap.add_argument("--dry-run", action="store_true")
    ap.add_argument("--source", default="cli")
    ap.add_argument("--delay", type=float, default=0.0)
    args = ap.parse_args(argv)
    if args.delay > 0:
        time.sleep(args.delay)
        wake_marker = (args.root / "data" / "orchestration" /
                       "refill_backoff_wake.json")
        wake = read_json(wake_marker, {}) or {}
        if isinstance(wake, dict) and int(wake.get("pid", -1) or -1) == os.getpid():
            try:
                wake_marker.unlink()
            except FileNotFoundError:
                pass
        print(json.dumps(schedule_run(args.root, source=args.source),
                         ensure_ascii=False))
        return 0
    try:
        rc, result = drain_requested(args.root, source=args.source,
                                     dry_run=args.dry_run,
                                     observe_timeout=args.observe_timeout)
    except (OSError, ValueError, RefillConsumerError) as exc:
        print(json.dumps({"status": "failed", "error": str(exc)}, ensure_ascii=False))
        return 3
    print(json.dumps({**result, "source": args.source, "ts": time.time()},
                     ensure_ascii=False))
    return rc


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Import an explicitly supplied parent manifest into the canonical packet ledger.

This is an admission boundary, not a watcher and not a dispatcher.  It reads
one manifest, validates that every task is an explicit read-only leaf packet,
and atomically creates packet files plus ``DISPATCHABLE`` ledger entries.  A
later refill transaction remains the only code allowed to turn those entries
into births.

The importer deliberately does not infer work from Desktop history, a UI
deficit, or an arbitrary parent rollout.  The caller must name the manifest
path explicitly.  That keeps the old parent watcher from becoming a second
scheduler while still providing the missing parent -> ledger handoff.
"""
from __future__ import annotations

import argparse
import hashlib
import json
import re
import sys
from pathlib import Path
from typing import Any, Mapping

try:
    from orchestration_common import (LoopPaths, RefillPolicy, append_ndjson,
                                      atomic_write_json, file_lock, read_json)
except ImportError:  # pragma: no cover - direct execution
    sys.path.insert(0, str(Path(__file__).resolve().parent))
    from orchestration_common import (LoopPaths, RefillPolicy, append_ndjson,
                                      atomic_write_json, file_lock, read_json)


class ParentManifestError(ValueError):
    """A manifest is not admissible for the packet ledger."""


ID_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9._-]{0,95}\Z")
UUID_RE = re.compile(
    r"[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-"
    r"[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\Z"
)
ROLES = frozenset({"worker", "verifier", "reviewer", "plan_expander"})
K3_ROLES = frozenset({"verifier", "reviewer", "plan_expander"})
TERMINAL_PARENT_STATES = frozenset({
    "completed", "complete", "done", "failed", "cancelled", "canceled",
    "stopped", "terminated", "terminal", "dead_letter",
})
ACTIVE_PARENT_STATES = frozenset({
    "active", "running", "loaded", "execution", "in_progress", "pending",
})


def _text(value: Any, field: str, *, maximum: int = 20000) -> str:
    if not isinstance(value, str) or not value.strip():
        raise ParentManifestError(f"{field} must be a non-empty string")
    value = value.strip()
    if len(value) > maximum:
        raise ParentManifestError(f"{field} exceeds {maximum} characters")
    return value


def _id(value: Any, field: str) -> str:
    value = _text(value, field, maximum=96)
    if not ID_RE.fullmatch(value):
        raise ParentManifestError(f"{field} has invalid id syntax")
    return value


def _list_of_text(value: Any, field: str, *, nonempty: bool = True) -> list[str]:
    if not isinstance(value, list) or (nonempty and not value):
        raise ParentManifestError(f"{field} must be a non-empty list")
    out: list[str] = []
    for index, item in enumerate(value):
        out.append(_text(item, f"{field}[{index}]", maximum=4000))
    return out


def _relative_authorized_paths(value: Any, field: str) -> list[str]:
    paths = _list_of_text(value, field)
    for item in paths:
        path = item.replace("\\", "/")
        if path.startswith("/") or re.match(r"^[A-Za-z]:/", path):
            raise ParentManifestError(f"{field} must contain relative paths")
        parts = [part for part in path.split("/") if part not in ("", ".")]
        if ".." in parts:
            raise ParentManifestError(f"{field} may not escape the task cwd")
    return paths


def allowed_workspace_roots(root: Path,
                            extra_roots: list[Path] | tuple[Path, ...] = ()) -> tuple[Path, ...]:
    """Return explicit read roots; never derive roots from task input."""
    candidates = [root.resolve(), *(Path(item).resolve() for item in extra_roots)]
    out: list[Path] = []
    for candidate in candidates:
        if candidate not in out and candidate.is_dir():
            out.append(candidate)
    return tuple(out)


def _safe_cwd(value: Any, root: Path,
              extra_roots: list[Path] | tuple[Path, ...] = ()) -> str:
    raw = _text(value, "cwd", maximum=1000)
    raw_path = raw.replace("\\", "/")
    if ".." in [part for part in raw_path.split("/") if part]:
        raise ParentManifestError("cwd may not contain parent traversal segments")
    try:
        raw_path_obj = Path(raw).expanduser()
        cwd = (raw_path_obj if raw_path_obj.is_absolute()
               else root / raw_path_obj).resolve()
    except OSError as exc:
        raise ParentManifestError(f"cwd cannot be resolved: {exc}") from exc
    roots = allowed_workspace_roots(root, extra_roots)
    if not any(cwd == allowed or allowed in cwd.parents for allowed in roots):
        raise ParentManifestError(
            f"cwd is outside the explicit read-only workspaces: {cwd}")
    if not cwd.is_dir():
        raise ParentManifestError(f"cwd is not an existing directory: {cwd}")
    return str(cwd)


def _parent_state(doc: Mapping[str, Any]) -> str | None:
    value = doc.get("parent_state", doc.get("status", doc.get("state")))
    if value is None:
        return None
    state = _text(value, "parent_state", maximum=64).lower()
    if state in TERMINAL_PARENT_STATES:
        raise ParentManifestError(f"parent_inactive: terminal parent state {state}")
    if state not in ACTIVE_PARENT_STATES:
        raise ParentManifestError(f"parent_inactive: unsupported parent state {state}")
    return state


def validate_manifest(doc: Any, root: Path,
                      extra_roots: list[Path] | tuple[Path, ...] = ()) -> dict[str, Any]:
    if not isinstance(doc, dict):
        raise ParentManifestError("manifest must be a JSON object")
    if doc.get("schema") != "codex-loop-parent-refill/v1":
        raise ParentManifestError("unsupported or missing manifest schema")
    manifest_id = _id(doc.get("manifest_id"), "manifest_id")
    parent_session_id = _text(doc.get("parent_session_id"), "parent_session_id", maximum=64)
    if not UUID_RE.fullmatch(parent_session_id):
        raise ParentManifestError("parent_session_id must be a UUID")
    if doc.get("enabled") is not True:
        raise ParentManifestError("parent_inactive: enabled must be true")
    if doc.get("mode") != "read-only":
        raise ParentManifestError("only mode=read-only is accepted")
    _parent_state(doc)
    max_active = RefillPolicy.load(LoopPaths.resolve(root)).target_total()
    target = doc.get("target_active")
    if (not isinstance(target, int) or isinstance(target, bool)
            or not 1 <= target <= max_active):
        raise ParentManifestError(
            f"target_active must be an integer in [1, {max_active}]")
    cwd = _safe_cwd(doc.get("cwd"), root, extra_roots)
    tasks = doc.get("tasks")
    if not isinstance(tasks, list) or not tasks:
        raise ParentManifestError("tasks must be a non-empty list")
    if len(tasks) > max_active:
        raise ParentManifestError(
            f"manifest may contain at most {max_active} tasks")
    seen: set[str] = set()
    clean_tasks: list[dict[str, Any]] = []
    for index, task in enumerate(tasks):
        if not isinstance(task, dict):
            raise ParentManifestError(f"tasks[{index}] must be an object")
        task_id = _id(task.get("task_id"), f"tasks[{index}].task_id")
        if task_id in seen:
            raise ParentManifestError(f"duplicate task_id {task_id}")
        seen.add(task_id)
        task_name = _text(task.get("task_name"), f"tasks[{index}].task_name", maximum=160)
        role = task.get("role")
        if role not in ROLES:
            raise ParentManifestError(
                f"tasks[{index}].role must be explicit worker/verifier/reviewer/plan_expander")
        if task.get("sandbox") != "read-only":
            raise ParentManifestError(f"tasks[{index}] must set sandbox=read-only")
        if task.get("allow_write") is True or task.get("workspace_write") is True:
            raise ParentManifestError(f"tasks[{index}] contains a write authorization")
        goal = task.get("goal", task.get("prompt"))
        goal = _text(goal, f"tasks[{index}].goal", maximum=20000)
        authorized = _relative_authorized_paths(
            task.get("authorized_paths"), f"tasks[{index}].authorized_paths")
        acceptance = _list_of_text(task.get("acceptance"),
                                   f"tasks[{index}].acceptance")
        clean_tasks.append({
            "task_id": task_id,
            "task_name": task_name,
            "goal": goal,
            "authorized_paths": authorized,
            "acceptance": acceptance,
            "role": role,
            "sandbox": "read-only",
            "cwd": _safe_cwd(task.get("cwd", cwd), root, extra_roots),
        })
    return {
        "schema": doc["schema"], "manifest_id": manifest_id,
        "parent_session_id": parent_session_id, "enabled": True,
        "target_active": target, "cwd": cwd, "mode": "read-only",
        "tasks": clean_tasks,
    }


def packet_id_for(manifest_id: str, task_id: str) -> str:
    digest = hashlib.sha256(f"{manifest_id}\0{task_id}".encode("utf-8")).hexdigest()
    return f"parent-{digest[:48]}"


def _canonical(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


def import_manifest(root: Path | str, manifest: Path | str, *,
                    allow_roots: list[Path] | tuple[Path, ...] = ()) -> dict[str, Any]:
    paths = LoopPaths.resolve(root)
    root_path = paths.root
    manifest_path = Path(manifest).expanduser().resolve()
    try:
        doc = json.loads(manifest_path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as exc:
        raise ParentManifestError(f"manifest unreadable: {exc}") from exc
    clean = validate_manifest(doc, root_path, allow_roots)
    manifest_id = clean["manifest_id"]
    parent_state_path = paths.refill_dir / "parent_sessions.json"
    with file_lock(paths.refill_dir / ".parent_sessions.lock"):
        parent_states = read_json(parent_state_path, {"parents": {}}) or {"parents": {}}
        prior_parent = (parent_states.get("parents") or {}).get(
            clean["parent_session_id"])
        if (isinstance(prior_parent, dict)
                and prior_parent.get("active") is False
                and prior_parent.get("manifest_id") == manifest_id):
            raise ParentManifestError(
                "parent_inactive: stopped parent cannot be implicitly reactivated")
    packet_dir = paths.data / "packets"
    packet_dir.mkdir(parents=True, exist_ok=True)
    # Reuse the deployed ledger lock name.  A second dot-prefixed lock would
    # look protected while remaining invisible to existing operators/tools.
    ledger_lock = paths.data / "progress_ledger.lock"
    imported = 0
    existing = 0
    with file_lock(ledger_lock):
        ledger = read_json(paths.ledger, {"packets": {}}) or {"packets": {}}
        if not isinstance(ledger, dict) or not isinstance(ledger.get("packets", {}), dict):
            raise ParentManifestError("progress ledger is unreadable or has invalid packets")
        packets = ledger["packets"]
        planned: list[tuple[Path, dict[str, Any], str, dict[str, Any], bool, bool]] = []
        for task in clean["tasks"]:
            packet_id = packet_id_for(manifest_id, task["task_id"])
            packet = {
                "packet_id": packet_id, "goal": task["goal"],
                "authorized_paths": task["authorized_paths"],
                "acceptance": task["acceptance"], "constraints": ["read-only"],
                "task_name": task["task_name"], "role": task["role"],
                "sandbox": "read-only", "cwd": task["cwd"],
                "parent_session_id": clean["parent_session_id"],
                "manifest_id": manifest_id, "parent_enabled": True,
                "created_by": "parent_manifest_importer",
            }
            entry = {
                "state": "DISPATCHABLE", "role": task["role"],
                "history": [], "attempts": 0,
                "pool_hint": "k3" if task["role"] in K3_ROLES else "v4",
                "task_name": task["task_name"], "goal": task["goal"],
                "parent_session_id": clean["parent_session_id"],
                "manifest_id": manifest_id, "parent_enabled": True,
                "created_by": "parent_manifest_importer", "sandbox": "read-only",
                "cwd": task["cwd"], "authorized_paths": task["authorized_paths"],
                "acceptance": task["acceptance"],
            }
            packet_path = packet_dir / f"{packet_id}.json"
            prior_packet = read_json(packet_path, None)
            prior_entry = packets.get(packet_id)
            if prior_packet is not None or prior_entry is not None:
                # Ledger lifecycle fields evolve after admission.  Idempotent
                # re-import compares only the immutable admission contract;
                # state/history/attempts/current_run_id must not make a valid
                # manifest look like a collision, while any task metadata
                # change remains a hard fail.
                immutable_entry = {key: value for key, value in entry.items()
                                   if key not in {"state", "history", "attempts"}}
                prior_immutable = ({key: prior_entry.get(key)
                                    for key in immutable_entry}
                                   if isinstance(prior_entry, dict) else None)
                if ((prior_packet is not None and prior_packet != packet)
                        or (prior_entry is not None
                            and prior_immutable != immutable_entry)):
                    raise ParentManifestError(
                        f"packet collision or content mismatch: {packet_id}")
                if prior_packet is not None and prior_entry is not None:
                    existing += 1
                    continue
            # A crash can happen between the packet-file replace and the
            # ledger replace.  Exact one-sided state is recoverable; different
            # content above remains a hard collision.
            planned.append((packet_path, packet, packet_id, entry,
                            prior_packet is None, prior_entry is None))
        # The entire batch is validated before the first production write.
        # A collision in task N therefore cannot leave tasks 1..N-1 imported.
        for packet_path, packet, packet_id, entry, write_packet, write_entry in planned:
            if write_packet:
                atomic_write_json(packet_path, packet)
            if write_entry:
                packets[packet_id] = entry
            imported += 1
        ledger["schema"] = ledger.get("schema", "codex-loop-statemachine/v2")
        atomic_write_json(paths.ledger, ledger)
    with file_lock(paths.refill_dir / ".parent_sessions.lock"):
        parent_states = read_json(parent_state_path, {"parents": {}}) or {"parents": {}}
        parents = parent_states.setdefault("parents", {})
        parents[clean["parent_session_id"]] = {
            "active": True, "manifest_id": manifest_id,
            "updated_at": __import__("time").time(),
            "source": "parent_manifest_importer",
        }
        atomic_write_json(parent_state_path, parent_states)
    append_ndjson(paths.events, {
        "ts": __import__("time").time(), "event": "parent_manifest_imported",
        "manifest_id": manifest_id, "parent_session_id": clean["parent_session_id"],
        "imported": imported, "existing": existing,
        "packet_ids": [packet_id_for(manifest_id, task["task_id"])
                        for task in clean["tasks"]],
        "created_by": "parent_manifest_importer",
    }, lock_path=paths.events_lock)
    # Admission creates durable demand.  Wake the existing coalesced
    # packet-only actuator immediately; otherwise a perfectly valid manifest
    # can sit DISPATCHABLE until an unrelated child happens to terminate.
    # This is a wake, not a second scheduler: the consumer re-reads the ledger,
    # enforces parent/model/capacity gates and suppresses already-active runs.
    try:
        from refill_consumer_v2 import schedule_run
        actuator = schedule_run(paths.root, source="parent_manifest_imported")
    except (ImportError, OSError, ValueError) as exc:
        actuator = {"status": "failed", "error": "%s: %s" %
                    (type(exc).__name__, exc)}
        append_ndjson(paths.events, {
            "ts": __import__("time").time(), "event": "refill_actuator_failed",
            "source": "parent_manifest_imported", "manifest_id": manifest_id,
            "error": actuator["error"],
        }, lock_path=paths.events_lock)
    return {"status": "imported" if imported else "existing",
            "manifest_id": manifest_id, "parent_session_id": clean["parent_session_id"],
            "imported": imported, "existing": existing,
            "packet_ids": [packet_id_for(manifest_id, task["task_id"])
                            for task in clean["tasks"]],
            "actuator": actuator}


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Import an explicit read-only parent manifest")
    parser.add_argument("--root", type=Path, required=True)
    parser.add_argument("--manifest", type=Path, required=True)
    parser.add_argument("--allow-root", type=Path, action="append", default=[],
                        help="explicit additional read-only workspace root")
    args = parser.parse_args(argv)
    try:
        print(json.dumps(import_manifest(args.root, args.manifest,
                                         allow_roots=args.allow_root), ensure_ascii=False))
        return 0
    except (OSError, ValueError) as exc:
        print(json.dumps({"status": "blocked", "error": str(exc)}, ensure_ascii=False))
        return 3


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Light terminal transaction: consume lifecycle events, then refill packets."""
from __future__ import annotations

import json
import os
import subprocess
import sys
import time
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = Path(os.environ.get("LOOP_ROOT", HERE.parent)).resolve()
sys.path.insert(0, str(HERE))

from orchestration_common import LoopPaths, atomic_write_json, file_lock  # noqa: E402
from orchestration_common import read_json  # noqa: E402
from refill_consumer_v2 import run_once as run_refill_once  # noqa: E402
from statemachine_v2 import StateMachine  # noqa: E402


def _failure_text(paths: LoopPaths, packet_id: str, state: str) -> str:
    roster = read_json(paths.data / "lifecycle" / "exec_roster.json",
                       {"jobs": {}}) or {"jobs": {}}
    job = (roster.get("jobs") or {}).get(packet_id, {})
    failure = job.get("failure") if isinstance(job, dict) else {}
    parts = [state]
    if isinstance(failure, dict):
        parts.extend(str(failure.get(key) or "")
                     for key in ("why", "error", "stderr_tail"))
    if isinstance(job, dict):
        parts.extend(str(job.get(key) or "")
                     for key in ("stop_reason", "exit_code"))
        stderr_path = job.get("stderr_path")
        if stderr_path:
            try:
                candidate = Path(str(stderr_path)).resolve()
                candidate.relative_to(paths.root)
                parts.append(candidate.read_text(
                    encoding="utf-8", errors="replace")[-8192:])
            except (OSError, ValueError):
                pass
    text = "\n".join(part for part in parts if part).strip()
    return text[:12000] or state


def route_terminal_retries(paths: LoopPaths,
                           states: dict[str, str]) -> list[dict[str, object]]:
    """Run the deterministic retry table for newly failed canonical packets."""
    routed: list[dict[str, object]] = []
    for packet_id, state in states.items():
        if state not in {"FAILED", "TIMED_OUT"}:
            continue
        proc = subprocess.run(
            [sys.executable, str(paths.root / "harness" / "retry.py"),
             "--packet", packet_id, "--error",
             _failure_text(paths, packet_id, state)],
            cwd=str(paths.root), env={**os.environ, "LOOP_ROOT": str(paths.root)},
            stdin=subprocess.DEVNULL, capture_output=True, text=True,
            timeout=30.0, check=False)
        routed.append({"packet_id": packet_id, "from_state": state,
                       "rc": proc.returncode,
                       "decision": proc.stdout.strip()[-2000:],
                       "stderr": proc.stderr.strip()[-2000:]})
    return routed


def normalize_legacy_reports(paths: LoopPaths) -> list[str]:
    """Wrap plain reports from supervisors born before report envelopes.

    The exec roster and ledger run_id must agree and the child must have
    completed with exit code zero.  This makes the compatibility path no less
    strict than a freshly started supervisor.
    """
    ledger = read_json(paths.ledger, {"packets": {}}) or {"packets": {}}
    roster = read_json(paths.data / "lifecycle" / "exec_roster.json",
                       {"jobs": {}}) or {"jobs": {}}
    jobs = roster.get("jobs") if isinstance(roster, dict) else {}
    jobs = jobs if isinstance(jobs, dict) else {}
    wrapped: list[str] = []
    for packet_id, entry in (ledger.get("packets") or {}).items():
        if not isinstance(entry, dict) or entry.get("state") != "RUNNING":
            continue
        job = jobs.get(packet_id)
        if (not isinstance(job, dict) or job.get("state") != "completed"
                or int(job.get("exit_code", 1) or 0) != 0
                or not job.get("run_id")
                or str(job.get("run_id")) != str(entry.get("current_run_id"))):
            continue
        report = paths.data / "reports" / packet_id / "report.json"
        if not report.is_file():
            continue
        raw = report.read_bytes()
        try:
            value = json.loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, ValueError):
            value = None
        if isinstance(value, dict) and value.get("packet_id") == packet_id:
            continue
        atomic_write_json(report, {
            "packet_id": packet_id, "status": "done",
            "run_id": str(job["run_id"]),
            "summary": raw.decode("utf-8", errors="replace"),
            "compatibility_envelope": True,
        })
        wrapped.append(packet_id)
    return wrapped


def run(root: Path = ROOT) -> dict[str, object]:
    result: dict[str, object] = {"schema": "codex-loop-terminal-packet/v1",
                                "ts": time.time(), "status": "PASS"}
    errors: list[str] = []
    orchestration = root / "data" / "orchestration"
    requests = orchestration / "terminal_requests.json"
    marker = orchestration / "terminal_epilogue.pid"
    claim = orchestration / ".terminal_epilogue.lock"
    with file_lock(orchestration / ".terminal_packet.lock"):
        paths = LoopPaths.resolve(root)
        while True:
            request_state = read_json(requests, {"requested_seq": 1,
                                                  "consumed_seq": 0}) or {}
            requested = int(request_state.get("requested_seq", 1) or 1)
            try:
                result["legacy_reports_wrapped"] = normalize_legacy_reports(paths)
            except Exception as exc:
                errors.append("report_normalize: %s: %s" %
                              (type(exc).__name__, exc))
            try:
                states = StateMachine(paths).step()
                result["state_machine"] = states
                result["retry_routes"] = route_terminal_retries(paths, states)
                for route in result["retry_routes"]:
                    if route.get("rc") not in {0, 4, 5, 6}:
                        errors.append("retry_route: packet=%s rc=%s stderr=%s" %
                                      (route.get("packet_id"), route.get("rc"),
                                       route.get("stderr")))
                if result["retry_routes"]:
                    result["state_machine_after_retry"] = StateMachine(paths).step()
            except Exception as exc:
                errors.append("state_machine: %s: %s" % (type(exc).__name__, exc))
            try:
                rc, refill = run_refill_once(root, dry_run=False)
                result["refill"] = refill
                if rc:
                    errors.append("refill: actuator rc=%d" % rc)
            except Exception as exc:
                errors.append("refill: %s: %s" % (type(exc).__name__, exc))
            with file_lock(claim):
                latest = read_json(requests, None)
                if not isinstance(latest, dict):
                    raise RuntimeError("terminal request state unreadable; refusing to consume edge")
                latest["consumed_seq"] = max(
                    int(latest.get("consumed_seq", 0) or 0), requested)
                latest["consumed_at"] = time.time()
                atomic_write_json(requests, latest)
                if int(latest.get("requested_seq", 0) or 0) <= requested:
                    marker_value = read_json(marker, {}) or {}
                    if (isinstance(marker_value, dict)
                            and int(marker_value.get("pid", -1) or -1) == os.getpid()):
                        try:
                            marker.unlink()
                        except FileNotFoundError:
                            pass
                    result["requested_seq"] = requested
                    result["consumed_seq"] = latest["consumed_seq"]
                    break
    if errors:
        result["status"] = "FAIL_VISIBLE"
        result["errors"] = errors
    atomic_write_json(root / "data" / "orchestration" /
                      "terminal_packet_status.json", result)
    return result


if __name__ == "__main__":
    print(json.dumps(run(), ensure_ascii=False))
